create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','treasurer','council');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role public.app_role not null default 'council',created_at timestamptz not null default now());
create table if not exists public.gl_codes(code text primary key,description text not null);
create table if not exists public.budgets(id bigint generated always as identity primary key,gl_code text not null references public.gl_codes(code),amount numeric(12,2) not null default 0,comments text,prior_budget numeric(12,2),prior_actual numeric(12,2),updated_at timestamptz not null default now(),unique(gl_code));
create table if not exists public.actuals(id bigint generated always as identity primary key,date date not null,gl_code text references public.gl_codes(code),amount numeric(12,2) not null,description text,school_month int,created_at timestamptz not null default now());
create table if not exists public.bank_transactions(id bigint generated always as identity primary key,date date not null,transaction text not null,withdrawal numeric(12,2) default 0,deposit numeric(12,2) default 0,balance numeric(12,2),gl_code text references public.gl_codes(code),description text,amount numeric(12,2) default 0,reconciled boolean not null default false,reconciled_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.cheques(id bigint generated always as identity primary key,cheque_no text not null,gl_code text references public.gl_codes(code),amount numeric(12,2) not null,cheque_date date not null,cleared_date date,vendor text,description text,invoice_no text,voided boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.fundraisers(id bigint generated always as identity primary key,name text not null,event_date date,status text not null default 'planned',notes text,created_at timestamptz not null default now());
create table if not exists public.fundraiser_entries(id bigint generated always as identity primary key,fundraiser_id bigint not null references public.fundraisers(id) on delete cascade,entry_type text not null check(entry_type in ('revenue','expense')),amount numeric(12,2) not null,description text,transaction_date date not null,gl_code text references public.gl_codes(code));
create table if not exists public.audit_log(id bigint generated always as identity primary key,user_id uuid references auth.users(id),action text not null,entity text not null,entity_id text,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
create table if not exists public.budget_snapshots(id uuid primary key default gen_random_uuid(),snapshot_date date not null default current_date,label text,created_by uuid references auth.users(id),data jsonb not null,created_at timestamptz not null default now());
create unique index if not exists budget_snapshot_daily on public.budget_snapshots(snapshot_date);
create table if not exists public.database_backups(id uuid primary key default gen_random_uuid(),label text not null,created_by uuid references auth.users(id),payload jsonb not null,created_at timestamptz not null default now());

create or replace function public.my_role() returns public.app_role language sql stable security definer set search_path=public as $$ select coalesce((select role from public.profiles where id=auth.uid()),'council'::public.app_role) $$;
create or replace function public.can_write() returns boolean language sql stable as $$ select public.my_role() in ('admin','treasurer') $$;
create or replace function public.is_admin() returns boolean language sql stable as $$ select public.my_role()='admin' $$;
create or replace function public.make_budget_snapshot(p_label text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare sid uuid; begin if not public.can_write() then raise exception 'not authorized'; end if; insert into budget_snapshots(snapshot_date,label,created_by,data) values(current_date,p_label,auth.uid(),(select coalesce(jsonb_agg(to_jsonb(b) order by b.gl_code),'[]'::jsonb) from budgets b)) on conflict(snapshot_date) do update set data=excluded.data,label=coalesce(excluded.label,budget_snapshots.label),created_by=excluded.created_by,created_at=now() returning id into sid; return sid; end $$;
create or replace function public.restore_budget_snapshot(p_snapshot uuid) returns void language plpgsql security definer set search_path=public as $$ declare snap jsonb; begin if not public.is_admin() then raise exception 'admin required'; end if; perform public.make_budget_snapshot('Automatic pre-restore snapshot'); select data into snap from budget_snapshots where id=p_snapshot; if snap is null then raise exception 'snapshot not found'; end if; delete from budgets; insert into budgets(id,gl_code,amount,comments,prior_budget,prior_actual,updated_at) select x.id,x.gl_code,x.amount,x.comments,x.prior_budget,x.prior_actual,now() from jsonb_to_recordset(snap) as x(id bigint,gl_code text,amount numeric,comments text,prior_budget numeric,prior_actual numeric,updated_at timestamptz); perform setval(pg_get_serial_sequence('budgets','id'),coalesce((select max(id) from budgets),1)); insert into audit_log(user_id,action,entity,entity_id,after_data) values(auth.uid(),'restore','budget_snapshot',p_snapshot::text,jsonb_build_object('restored_at',now())); end $$;

alter table public.profiles enable row level security;alter table public.gl_codes enable row level security;alter table public.budgets enable row level security;alter table public.actuals enable row level security;alter table public.bank_transactions enable row level security;alter table public.cheques enable row level security;alter table public.fundraisers enable row level security;alter table public.fundraiser_entries enable row level security;alter table public.audit_log enable row level security;alter table public.budget_snapshots enable row level security;alter table public.database_backups enable row level security;
do $$ declare t text; begin foreach t in array array['gl_codes','budgets','actuals','bank_transactions','cheques','fundraisers','fundraiser_entries'] loop execute format('create policy "authenticated read %1$s" on public.%1$I for select to authenticated using (true)',t); execute format('create policy "finance write %1$s" on public.%1$I for all to authenticated using (public.can_write()) with check (public.can_write())',t); end loop; end $$;
create policy "profile self read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "profile admin write" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "audit read" on public.audit_log for select to authenticated using(public.my_role() in ('admin','treasurer'));
create policy "snapshot read" on public.budget_snapshots for select to authenticated using(true);
create policy "snapshot write" on public.budget_snapshots for insert to authenticated with check(public.can_write());
create policy "backup read" on public.database_backups for select to authenticated using(public.my_role() in ('admin','treasurer'));
create policy "backup write" on public.database_backups for all to authenticated using(public.my_role() in ('admin','treasurer')) with check(public.my_role() in ('admin','treasurer'));
